/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const {
        dropdownItemId
    } = event.payload;
    let route = '';
    let fields = {};

    switch (dropdownItemId) {
        case 'from_url':
            {
                route = 'external-url-font-creation-content';
                fields = {
                    fontName: api.state.urlBasedFontData.header_font_name,
                    fontAddress: api.state.urlBasedFontData.header_font_src,
                }
                break;
            }

        case 'upload_font':
            {
                route = 'font-asset-upload-content';
                break;
            }
    }
    return {
        viewportElementId: 'viewport_psg',
        route: route,
        fields: fields,
        params: null
    };
}

